; Program 5.87: Uniform random numbers by (5.69), mapped to [a, b]: X(n) = a + (b − a)·V(n)
; Source: Дьяконов, «Справочник по расчётам на микрокалькуляторах», 1985, p.139 (book61.pdf page 140)
; Input: a in Ra, b in Rb, V0 in R0. Output: each С/П gives the next X(n); V(n) in R0.
;
; Book example: a = 2, b = 3, V0 = 0,1234567 -> 2,5678979; 2,012222; 2,452214
; @reg Ra=2 Rb=3 R0=0.1234567
; @run
; @expect X=2.5678979
; @run
; @expect X=2.012222
; @run
; @expect X=2.452214
;
; MK56-ASM form of 05-87-random-ab.mk56, generated by mk56asm -s.
; Each comment gives the address, the keys as printed and the codes.

L00:
        RCL R0          ; 00  ИП0            60
        37              ; 01  3 7            03 07
        MUL             ; 03  ×              12
        1               ; 04  1              01
        ADD             ; 05  +              10
        STO RD          ; 06  Пd             4D
        RCL (RD)        ; 07  КИПd           DD
        SWAP            ; 08  ↔              14
        RCL RD          ; 09  ИПd            6D
        SUB             ; 10  −              11
        STO R0          ; 11  П0             40
        RCL RB          ; 12  ИПb            6B
        RCL RA          ; 13  ИПa            6A
        SUB             ; 14  −              11
        MUL             ; 15  ×              12
        RCL RA          ; 16  ИПa            6A
        ADD             ; 17  +              10
        HALT            ; 18  С/П            50
        JMP L00         ; 19  БП 00          51 00
